import numpy as np

def value_iteration(states, actions, transitions, rewards, gamma, threshold=1e-6, max_iter=1000):
    V = np.zeros(len(states))
    for iteration in range(max_iter):
        V_new = np.zeros(len(states))
        for s in range(len(states)):
            Q = []
            for a in range(len(actions)):
                q_val = sum(transitions[s][a][s_prime] * (rewards[s][a][s_prime] + gamma * V[s_prime]) for s_prime in range(len(states)))
                Q.append(q_val)
            V_new[s] = max(Q)
        if np.max(np.abs(V_new - V)) < threshold:
            break
        V = V_new
    policy = []
    for s in range(len(states)):
        Q = []
        for a in range(len(actions)):
            q_val = sum(transitions[s][a][s_prime] * (rewards[s][a][s_prime] + gamma * V[s_prime]) for s_prime in range(len(states)))
            Q.append(q_val)
        policy.append(np.argmax(Q))
    return {"V": V, "policy": policy, "iterations": iteration + 1}
